23	\centering
24	\includegraphics[width=0.88\textwidth]{frame-03-harness.jpg}
25	\caption{课程中强调 ``harness 与工具必须联合设计'' 的关键画面 \protect\footnotemark}
26	\end{figure}
27	\footnotetext{视频画面时间区间：00:26:24--00:26:55。}
