33	\centering
34	\begin{tabular}{p{3.2cm}p{4.4cm}p{3.8cm}p{2.6cm}}
35	\toprule
36	\textbf{控制流范式} & \textbf{优点} & \textbf{风险} & \textbf{适配任务} \\
37	\midrule
38	全动态 ReAct & 灵活探索、适应未知情况 & 轨迹漂移、成本不稳定 & 开放式定位与调试 \\
39	两阶段拼接循环 & 信息收集与补丁生成解耦 & 阶段边界错了会级联失败 & 中等复杂修复任务 \\
40	状态机约束循环 & 可控性强、便于审计与复现 & 搜索空间受限、可能错过解 & 高风险场景、合规流程 \\
41	\bottomrule
42	\end{tabular}
43	\caption{控制流设计是任务风险与探索能力之间的权衡}
44	\end{table}
45	
