62	\centering
63	\includegraphics[width=0.88\textwidth]{frame-04-control-loop.jpg}
64	\caption{围绕控制流与策略循环的讲解，强调动态循环和程序化约束并非对立 \protect\footnotemark}
65	\end{figure}
66	\footnotetext{视频画面时间区间：00:38:10--00:38:55。}
